const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);

test("AC-014 the ready message is shown after load", async ({ page }) => {
  await page.goto("index.html");
  await expect(page.locator("#message")).toHaveText("Press Start to begin a 30-second round.");
});

